-- Unmanned door (kiosk QR check-in) + pre-arrival invite links.

alter table public.events
  add column kiosk_enabled boolean not null default false,
  -- 32-byte hex HMAC key for the rotating door code. Generated by the API when kiosk mode is
  -- switched on, and regenerated every time it is re-enabled (kills any old photo of the QR).
  add column kiosk_secret  text;

alter table public.rsvps
  add column invited_at   timestamptz,           -- last pre-arrival link sent
  add column invite_count int not null default 0;

-- checked_in_by now also records 'kiosk' for self check-ins at the door screen.
comment on column public.rsvps.checked_in_by is 'staff email, or ''kiosk'' for QR self check-in';
